<?php $items = array(); foreach ( preg_split( '/\r?\n/', (string) get_theme_mod( 'kimpu_features_items', '' ) ) as $line ) { $parts = array_map( 'trim', explode( '|', $line ) ); if ( ! empty( $parts[0] ) ) { $items[] = array( 'title' => $parts[0], 'description' => isset( $parts[1] ) ? $parts[1] : '', 'icon' => isset( $parts[2] ) ? sanitize_key( $parts[2] ) : 'star' ); } } if ( ! $items ) { $items = array( array( 'title' => __( 'Modern design', 'kimpu-multipurpose' ), 'description' => __( 'Intentional spacing and clear typography.', 'kimpu-multipurpose' ), 'icon' => 'star' ), array( 'title' => __( 'Responsive layout', 'kimpu-multipurpose' ), 'description' => __( 'Beautiful on mobile, tablet, and desktop.', 'kimpu-multipurpose' ), 'icon' => 'grid' ), array( 'title' => __( 'Easy customization', 'kimpu-multipurpose' ), 'description' => __( 'Adjust your brand color and homepage message.', 'kimpu-multipurpose' ), 'icon' => 'check' ) ); } ?><section class="section <?php echo esc_attr( kimpu_homepage_section_classes( 'features' ) ); ?>" id="features"><div class="container"><?php kimpu_homepage_section_header( 'features' ); ?><div class="homepage-card-grid homepage-feature-grid homepage-columns-<?php echo 'four' === kimpu_homepage_section_value( 'features', 'layout', 'three' ) ? '4' : '3'; ?>"><?php foreach ( $items as $item ) : ?><article class="feature-card"><span class="feature-icon" aria-hidden="true"><?php echo esc_html( kimpu_homepage_icon( $item['icon'] ) ); ?></span><h3><?php echo esc_html( $item['title'] ); ?></h3><p><?php echo esc_html( $item['description'] ); ?></p></article><?php endforeach; ?></div></div></section>
